from bloomerp.models.communication.voip import PhoneCall

from .telnyx_fixtures import TelnyxFixtures


class TestTelnyxVoiceView(TelnyxFixtures, BloomerpViewTestCase):
    """Exercise Telnyx through the same generated voice route as other carriers."""

    view_name = "voip_voice"

    def retained_once(self, response: HttpResponse) -> bool:
        """Retain a single incoming call and activity despite repeated delivery."""
        return (
            PhoneCall.objects.filter(
                connection=self.connection, provider_call_id="v3:incoming"
            ).count()
            == 1
            and b"sip:gencredStaff@sip.telnyx.com" in response.content
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check signed routing, application isolation, replay and current line authorization."""
        return [
            RequestScenario(
                name="Telnyx incoming browser routing",
                method="POST",
                prepare=self.incoming,
                expected=ExpectedResult(response_validators=self.retained_once),
            ),
            RequestScenario(
                name="Telnyx duplicate incoming call",
                method="POST",
                prepare=self.replay,
                expected=ExpectedResult(response_validators=self.retained_once),
            ),
            RequestScenario(
                name="Telnyx reserved destination only",
                method="POST",
                prepare=self.outgoing,
                expected=ExpectedResult(
                    response_validators=self.contains_text(">+32470000002</Number>")
                ),
            ),
            RequestScenario(
                name="Unsigned Telnyx request rejected",
                method="POST",
                prepare=self.unsigned,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Stale signature rejected",
                method="POST",
                prepare=self.stale,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Cross-application signature rejected",
                method="POST",
                prepare=self.wrong_application,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Revoked reservation rejected",
                method="POST",
                prepare=self.revoked,
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Forged reservation rejected",
                method="POST",
                prepare=self.tampered,
                expected=ExpectedResult(status_code=403),
            ),
        ]
